package engine_test

import (
	"context"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/townsendmerino/ken/engine"
)

// envTree is a small repo with one file each walk limit can drop:
// a generated file, a minified one and a large one, beside a plain one.
func envTree(t *testing.T) string {
	t.Helper()
	return writeTree(t, map[string]string{
		"plain.go":     "package p\n\nfunc PlainMarker() {}\n",
		"generated.go": "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage p\n\nfunc GeneratedMarker() {}\n",
		"bundle.js":    "function minifiedMarker(){}" + strings.Repeat(";var a=1", 800) + "\n",
		"large.go":     "package p\n\nfunc LargeMarker() {}\n" + strings.Repeat("// padding line to grow the file\n", 400),
	})
}

// indexedFiles opens root with opts (bm25, so no model is needed) and
// returns which of envTree's files the index holds.
func indexedFiles(t *testing.T, root string, opts engine.Options) []string {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	opts.Mode = "bm25"
	ws, err := engine.Open(ctx, root, opts)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer func() { _ = ws.Close() }()
	seen := map[string]bool{}
	for _, q := range []string{"PlainMarker", "GeneratedMarker", "minifiedMarker", "LargeMarker"} {
		hits, err := ws.Search(ctx, q, 10)
		if err != nil {
			t.Fatalf("Search(%q): %v", q, err)
		}
		for _, h := range hits {
			seen[h.File] = true
		}
	}
	files := make([]string, 0, len(seen))
	for f := range seen {
		files = append(files, f)
	}
	sort.Strings(files)
	return files
}

// TestOpen_IgnoresEnvironment pins the contract Options' doc states: engine
// takes its whole configuration from Options. Every KEN_* variable that
// used to reach Open through internal/* is set to a value that would drop
// files or fail the build, and a zero Options must still index everything.
func TestOpen_IgnoresEnvironment(t *testing.T) {
	root := envTree(t)
	t.Setenv("KEN_MAX_FILE_BYTES", "1KiB")   // would drop large.go and bundle.js
	t.Setenv("KEN_MAX_AVG_LINE_BYTES", "10") // would drop nearly everything
	t.Setenv("KEN_MAX_FILES", "1")           // would fail Open
	t.Setenv("KEN_SKIP_GENERATED", "1")      // would drop generated.go
	t.Setenv("KEN_STRUCTURAL_MAX_FILE_BYTES", "10")
	t.Setenv("KEN_ENRICH", "off")
	t.Setenv("KEN_ANN", "flat-i8")

	got := indexedFiles(t, root, engine.Options{})
	// bundle.js is minified at the default threshold too, so the default
	// walk skips it; the other three are indexed.
	want := []string{"generated.go", "large.go", "plain.go"}
	if strings.Join(got, ",") != strings.Join(want, ",") {
		t.Errorf("zero Options with hostile KEN_* env indexed %v, want %v", got, want)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	ws, err := engine.Open(ctx, root, engine.Options{Mode: "bm25"})
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = ws.Close() }()
	if sites, err := ws.Definition(ctx, "PlainMarker"); err != nil || len(sites) != 1 {
		t.Errorf("Definition(PlainMarker) = %v, %v with KEN_STRUCTURAL_MAX_FILE_BYTES=10 set; want 1 site (the variable must be ignored)", sites, err)
	}
}

// TestOpen_WalkLimitOptions covers the Options fields that replace those
// variables for an in-process caller.
func TestOpen_WalkLimitOptions(t *testing.T) {
	root := envTree(t)
	for _, tc := range []struct {
		name string
		opts engine.Options
		want []string
	}{
		{"defaults", engine.Options{}, []string{"generated.go", "large.go", "plain.go"}},
		{"SkipGenerated", engine.Options{SkipGenerated: true}, []string{"large.go", "plain.go"}},
		{"MaxFileBytes", engine.Options{MaxFileBytes: 1 << 10}, []string{"generated.go", "plain.go"}},
		{"MaxAvgLineBytes off", engine.Options{MaxAvgLineBytes: -1}, []string{"bundle.js", "generated.go", "large.go", "plain.go"}},
		{"MaxFiles unlimited", engine.Options{MaxFiles: -1}, []string{"generated.go", "large.go", "plain.go"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := indexedFiles(t, root, tc.opts); strings.Join(got, ",") != strings.Join(tc.want, ",") {
				t.Errorf("indexed %v, want %v", got, tc.want)
			}
		})
	}

	t.Run("MaxFiles exceeded fails Open", func(t *testing.T) {
		ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
		defer cancel()
		ws, err := engine.Open(ctx, root, engine.Options{Mode: "bm25", MaxFiles: 2})
		if err == nil {
			_ = ws.Close()
			t.Fatal("Open succeeded on a 3-file root with MaxFiles: 2")
		}
	})
}
